import { AppText as Text } from '@makanza/mobile-ui';
import { useState } from 'react';
import { Alert, Platform, Pressable, StyleSheet, View } from 'react-native';
import type { VendorOrder } from '@makanza/mobile-core';
import FormField from '../components/FormField';
import { CancellationReasonModal, type CancellationReason } from '@makanza/mobile-ui';

type Props={order:VendorOrder;busy:boolean;dark:boolean;onAction:(id:string,status:string,reason?:string)=>void;onVerifyPickup:(id:string,code:string)=>void;onCancel:(id:string,reason:CancellationReason,details:string)=>void};
export default function OrderCard({order,busy,dark,onAction,onVerifyPickup,onCancel}:Props){
  const [pickupCode,setPickupCode]=useState('');
  const [cancelOpen,setCancelOpen]=useState(false);
  const next=order.status==='CONFIRMED'?['Accept order','ACCEPTED_BY_VENDOR']:order.status==='ACCEPTED_BY_VENDOR'?['Start preparing','PREPARING']:order.status==='PREPARING'?['Ready for pickup','READY_FOR_PICKUP']:null;
  const decline=()=>{if(Platform.OS==='web'){const reason=window.prompt('Reason: enter NOT_AVAILABLE or OUT_OF_STOCK','NOT_AVAILABLE');if(reason==='NOT_AVAILABLE'||reason==='OUT_OF_STOCK')onAction(order.id,'REJECTED',reason);return;}Alert.alert('Decline this order?','Choose a reason to share with the customer.',[{text:'Cancel',style:'cancel'},{text:'Not available',onPress:()=>onAction(order.id,'REJECTED','NOT_AVAILABLE')},{text:'Out of stock',style:'destructive',onPress:()=>onAction(order.id,'REJECTED','OUT_OF_STOCK')}]);};
  const statusLabel=order.status==='PICKED_UP'?'On the way':order.status.replaceAll('_',' ').toLowerCase();
  return <View style={[s.card,dark&&s.cardDark]}>
    <View style={s.row}><Text style={[s.id,dark&&s.lightText]}>Order {order.id.slice(-8)}</Text><Text style={s.status}>{statusLabel}</Text></View>
    <Text style={[s.items,dark&&s.mutedDark]}>{order.items.map(line=>`${line.quantity} × ${line.nameSnapshot}${line.addons?.length?` (+ ${line.addons.map(extra=>`${extra.quantity*line.quantity} ${extra.nameSnapshot}`).join(', ')})`:''}`).join(' · ')}</Text>
    <View style={s.row}><Text style={[s.date,dark&&s.mutedDark]}>{new Date(order.createdAt).toLocaleString()}</Text><Text style={s.total}>₦{(order.totalMinor/100).toLocaleString('en-NG')}</Text></View>
    {order.delivery?.status==='ASSIGNED'&&!order.delivery.pickupVerified&&<View style={s.pickupCode}><Text style={s.pickupLabel}>VERIFY RIDER PICKUP</Text><Text style={[s.date,dark&&s.mutedDark]}>Ask the rider to show the six-digit pickup code in their app, then enter it here.</Text><FormField label="Rider pickup code" value={pickupCode} onChangeText={value=>setPickupCode(value.replace(/\D/g,'').slice(0,6))} placeholder="6 digit code" keyboardType="number-pad" maxLength={6} dark={dark}/><Pressable accessibilityRole="button" onPress={()=>onVerifyPickup(order.id,pickupCode)} disabled={busy||pickupCode.length!==6} style={[s.button,busy&&s.disabled]}><Text style={s.buttonText}>{busy?'Verifying…':'Verify rider pickup'}</Text></Pressable></View>}
    {order.delivery?.pickupVerified&&<View style={s.pickupCode}><Text style={s.pickupLabel}>PICKUP VERIFIED</Text><Text style={[s.date,dark&&s.mutedDark]}>The rider can continue to the customer.</Text></View>}
    {['CONFIRMED','ACCEPTED_BY_VENDOR','PREPARING','READY_FOR_PICKUP','RIDER_ASSIGNED'].includes(order.status)&&<Pressable accessibilityRole="button" onPress={()=>setCancelOpen(true)} disabled={busy} style={s.reject}><Text style={s.rejectText}>Cancel order</Text></Pressable>}
    {next&&<View style={s.actions}>{order.status==='CONFIRMED'&&<Pressable accessibilityRole="button" onPress={decline} disabled={busy} style={s.reject}><Text style={s.rejectText}>Decline</Text></Pressable>}<Pressable accessibilityRole="button" onPress={()=>onAction(order.id,next[1])} disabled={busy} style={[s.button,busy&&s.disabled]}><Text style={s.buttonText}>{busy?'Updating…':next[0]}</Text></Pressable></View>}
    <CancellationReasonModal visible={cancelOpen} role="VENDOR" dark={dark} busy={busy} onClose={()=>setCancelOpen(false)} onSubmit={(reason,details)=>{setCancelOpen(false);onCancel(order.id,reason,details)}}/>
  </View>;
}
const s=StyleSheet.create({card:{padding:15,gap:11,borderWidth:0,borderColor:'transparent',borderRadius:0,backgroundColor:'transparent',borderBottomWidth:1,borderBottomColor:'#e4e7de',shadowOpacity:0,elevation:0},cardDark:{borderWidth:0,borderColor:'transparent',borderRadius:0,backgroundColor:'transparent',borderBottomWidth:1,borderBottomColor:'#e4e7de',shadowOpacity:0,elevation:0},row:{flexDirection:'row',alignItems:'center',justifyContent:'space-between',gap:10},id:{fontSize:15,fontWeight:'800',color:'#192b23'},status:{fontSize:11,color:'#194c3a',backgroundColor:'#eef3e4',paddingHorizontal:8,paddingVertical:5,borderRadius:0,textTransform:'capitalize'},items:{fontSize:13,lineHeight:21,color:'#69766a'},date:{fontSize:11,color:'#79817a',flex:1},total:{fontSize:13,fontWeight:'900',color:'#194c3a'},pickupCode:{padding:12,borderRadius:0,backgroundColor:'#eef3e4',gap:4},pickupLabel:{fontSize:10,fontWeight:'900',letterSpacing:1,color:'#194c3a'},pickupValue:{fontSize:26,letterSpacing:5,fontWeight:'900',color:'#192b23'},actions:{flexDirection:'row',gap:8,justifyContent:'flex-end',marginTop:3},button:{minHeight:41,paddingHorizontal:15,borderRadius:0,backgroundColor:'#194c3a',justifyContent:'center',alignItems:'center'},buttonText:{fontSize:12,fontWeight:'800',color:'white'},reject:{minHeight:41,paddingHorizontal:15,borderRadius:0,borderWidth:1,borderColor:'#9aa99f',justifyContent:'center'},rejectText:{fontSize:12,fontWeight:'800',color:'#994739'},disabled:{opacity:.55},lightText:{color:'#edf3e9'},mutedDark:{color:'#aab4a8'}});
